namespace ROS2.Net.AppGen;

// AppTarget.cs: generated into every project so apps run unchanged against the simulator or a real robot.
public sealed partial class ProjectService
{
    /// <summary>Source of the <c>AppTarget</c> helper (global namespace) shared by every generated project.</summary>
    internal const string AppTargetSource = """
        // AppTarget — chooses between the simulator and a physical robot at run time (generated by ROS2AppGen).
        // ROS2AppGen's Run passes the choice as environment variables; you can also set them yourself:
        //   ROS2NET_TARGET=sim|robot   ROS2NET_RMW=inprocess|rtps|rosbridge   ROS_DOMAIN_ID=0
        //   ROS2NET_ROSBRIDGE_URL=ws://robot:9090   ROS2NET_ROBOT_NS=/robot1   ROS_LOCALHOST_ONLY=1
        //   ROS2NET_NETWORK_INTERFACE=192.168.1.10   ROS2NET_SIM_SCENARIO=Warehouse
        //   ROS2NET_MAX_LINEAR=0.3   ROS2NET_MAX_ANGULAR=1.0   (velocity limits; always set them for real robots)
        using System.Globalization;
        using ROS2.Net;
        using ROS2.Net.Msgs.GeometryMsgs;
        using ROS2.Net.Rmw;
        using ROS2.Net.Rmw.Rosbridge;
        using ROS2.Net.Rmw.Rtps;
        using ROS2.Net.Simulation;

        /// <summary>Whether the app drives the ROS2.Net simulator or a real robot.</summary>
        public enum AppTargetKind
        {
            Simulator,
            PhysicalRobot,
        }

        /// <summary>
        /// Run-time target selection. In <see cref="AppTargetKind.Simulator"/> mode the app starts a
        /// ROS2.Net.Simulation world so <c>cmd_vel</c>, <c>odom</c>, <c>scan</c> and friends exist;
        /// in <see cref="AppTargetKind.PhysicalRobot"/> mode no simulator runs and the app talks to the
        /// robot's own topics over RTPS (DDS) or rosbridge.
        /// </summary>
        public static class AppTarget
        {
            private static SimWorld? s_world;

            public static AppTargetKind Kind =>
                string.Equals(Env("ROS2NET_TARGET"), "robot", StringComparison.OrdinalIgnoreCase) ? AppTargetKind.PhysicalRobot : AppTargetKind.Simulator;

            public static bool IsSimulator => Kind == AppTargetKind.Simulator;

            public static bool IsPhysicalRobot => Kind == AppTargetKind.PhysicalRobot;

            /// <summary>Middleware: <c>inprocess</c> (default in simulator mode), <c>rtps</c> (default for robots) or <c>rosbridge</c>.</summary>
            public static string Rmw
            {
                get
                {
                    var rmw = Env("ROS2NET_RMW")?.Trim().ToLowerInvariant();
                    if (string.IsNullOrEmpty(rmw))
                    {
                        return IsSimulator ? "inprocess" : "rtps";
                    }

                    return IsPhysicalRobot && rmw == "inprocess" ? "rtps" : rmw;
                }
            }

            /// <summary>The robot namespace (e.g. <c>/robot1</c>), or empty for un-namespaced topics.</summary>
            public static string RobotNamespace => (Env("ROS2NET_ROBOT_NS") ?? string.Empty).Trim().TrimEnd('/');

            /// <summary>Simulator scenario, defaulting to <paramref name="fallback"/>.</summary>
            public static ScenarioKind Scenario(ScenarioKind fallback) =>
                Env("ROS2NET_SIM_SCENARIO") is { Length: > 0 } s && Enum.TryParse<ScenarioKind>(s, ignoreCase: true, out var k) ? k : fallback;

            /// <summary>Linear speed limit [m/s]. Real robots default to a conservative 0.3 m/s.</summary>
            public static double MaxLinearSpeed => Number("ROS2NET_MAX_LINEAR") ?? (IsPhysicalRobot ? 0.3 : 1.0);

            /// <summary>Angular speed limit [rad/s]. Real robots default to 1.0 rad/s.</summary>
            public static double MaxAngularSpeed => Number("ROS2NET_MAX_ANGULAR") ?? (IsPhysicalRobot ? 1.0 : 3.0);

            /// <summary>The simulated world (simulator mode, after <see cref="StartSimulator"/>), else null.</summary>
            public static SimWorld? World => s_world;

            /// <summary>A topic in the robot's namespace: <c>Topic("cmd_vel")</c> → <c>/cmd_vel</c> or <c>/robot1/cmd_vel</c>.</summary>
            public static string Topic(string name) => (RobotNamespace.Length == 0 ? string.Empty : (RobotNamespace.StartsWith('/') ? RobotNamespace : "/" + RobotNamespace)) + "/" + name.TrimStart('/');

            /// <summary>Context options for the selected middleware (and the app's command-line arguments).</summary>
            public static Ros2ContextOptions ContextOptions(string[]? args = null)
            {
                RmwRegistry.Register(new RtpsRmwFactory());
                RmwRegistry.Register(new RosbridgeRmwFactory());
                var options = new Ros2ContextOptions { Arguments = args, HandleShutdownSignals = true };
                options.Rmw = RmwRegistry.TryGet(Rmw, out var factory) ? factory : throw new InvalidOperationException($"Unknown middleware '{Rmw}'.");
                if (Env("ROS2NET_ROSBRIDGE_URL") is { Length: > 0 } url)
                {
                    options.RmwSettings["url"] = url;
                }

                if (Env("ROS2NET_NETWORK_INTERFACE") is { Length: > 0 } nic)
                {
                    options.RmwSettings["interface"] = nic;
                }

                return options;
            }

            /// <summary>Creates the ROS context for the selected target.</summary>
            public static Task<Ros2Context> CreateContextAsync(string[]? args = null) => Ros2Context.CreateAsync(ContextOptions(args));

            /// <summary>
            /// Simulator mode: builds the scenario, starts a <see cref="SimulationNode"/> and returns it.
            /// With one robot and no namespace the robot's topics are un-namespaced (/cmd_vel, /odom, /scan).
            /// Physical-robot mode: returns null (the real robot provides the topics).
            /// </summary>
            public static SimulationNode? StartSimulator(Ros2Context context, ScenarioKind defaultScenario, int robots = 1, SimulationNodeOptions? options = null, RobotSensorOptions? sensors = null)
            {
                if (!IsSimulator)
                {
                    return null;
                }

                var world = Scenarios.Create(Scenario(defaultScenario), robots: Math.Max(1, robots), sensors: sensors);
                if (world.Robots.Count == 1)
                {
                    world.Robots[0].Namespace = RobotNamespace.Length == 0 ? "/" : Topic(string.Empty).TrimEnd('/');
                }

                s_world = world;
                var sim = new SimulationNode(context, world, options);
                sim.Start();
                return sim;
            }

            /// <summary>Namespaces of the robots the app should drive (simulated fleet, or the one real robot).</summary>
            public static IReadOnlyList<string> RobotNamespaces() =>
                World is { } w && w.Robots.Count > 1
                    ? w.Robots.Select(r => "/" + r.Name).ToList()
                    : [RobotNamespace.Length == 0 ? string.Empty : Topic(string.Empty).TrimEnd('/')];

            /// <summary>
            /// SAFETY: clamps a velocity command to the configured limits. Always pass commands for a
            /// physical robot through this, keep an emergency stop within reach and test in open space first.
            /// </summary>
            public static Twist Limit(Twist cmd)
            {
                cmd.Linear.X = Math.Clamp(cmd.Linear.X, -MaxLinearSpeed, MaxLinearSpeed);
                cmd.Linear.Y = Math.Clamp(cmd.Linear.Y, -MaxLinearSpeed, MaxLinearSpeed);
                cmd.Angular.Z = Math.Clamp(cmd.Angular.Z, -MaxAngularSpeed, MaxAngularSpeed);
                return cmd;
            }

            /// <summary>One-line description of the target for start-up logs.</summary>
            public static string Describe() =>
                IsSimulator
                    ? $"target: simulator ({Rmw}{(RobotNamespace.Length > 0 ? ", ns " + RobotNamespace : string.Empty)})"
                    : $"target: PHYSICAL ROBOT via {Rmw}{(Rmw == "rosbridge" ? " " + Env("ROS2NET_ROSBRIDGE_URL") : string.Empty)}{(RobotNamespace.Length > 0 ? ", ns " + RobotNamespace : string.Empty)}, limits {MaxLinearSpeed:0.##} m/s / {MaxAngularSpeed:0.##} rad/s";

            private static string? Env(string name) => Environment.GetEnvironmentVariable(name);

            private static double? Number(string name) =>
                double.TryParse(Env(name), NumberStyles.Float, CultureInfo.InvariantCulture, out var v) && v > 0 ? v : null;
        }
        """;

    /// <summary>Blazor-only extension: configures the host and runs the simulator as a hosted service.</summary>
    internal const string AppTargetBlazorSource = """
        // AppTarget for Blazor apps (generated by ROS2AppGen).
        using ROS2.Net;
        using ROS2.Net.Hosting;
        using ROS2.Net.Simulation;

        public static class AppTargetHosting
        {
            /// <summary>Applies the selected target (middleware, rosbridge URL, interface) to the ROS host options.</summary>
            public static void Configure(Ros2HostOptions options)
            {
                options.ConfigureContext = context =>
                {
                    var target = AppTarget.ContextOptions();
                    context.Rmw = target.Rmw;
                    foreach (var (k, v) in target.RmwSettings)
                    {
                        context.RmwSettings[k] = v;
                    }
                };
            }
        }

        /// <summary>Starts the simulator in simulator mode (no-op for physical robots).</summary>
        public sealed class AppTargetSimulator(Ros2Context context) : IHostedService, IDisposable
        {
            private SimulationNode? _sim;

            /// <summary>Scenario used in simulator mode (override with ROS2NET_SIM_SCENARIO).</summary>
            public static ScenarioKind DefaultScenario { get; set; } = ScenarioKind.Office;

            public static int Robots { get; set; } = 1;

            public Task StartAsync(CancellationToken cancellationToken)
            {
                _sim = AppTarget.StartSimulator(context, DefaultScenario, Robots);
                return Task.CompletedTask;
            }

            public Task StopAsync(CancellationToken cancellationToken) => _sim?.StopAsync() ?? Task.CompletedTask;

            public void Dispose() => _sim?.Dispose();
        }
        """;
}
